function base64URLEncode(arrayBuffer) {
  return btoa(String.fromCharCode(...new Uint8Array(arrayBuffer)))
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_');
}

async function generateCodeChallenge(codeVerifier) {
  const encoder = new TextEncoder();
  const data = encoder.encode(codeVerifier);
  const digest = await crypto.subtle.digest('SHA-256', data);
  return base64URLEncode(digest);
}

function generateCodeVerifier() {
  // Generate 32 bytes of random data (43-128 chars is valid)
  const array = new Uint8Array(32);
  crypto.getRandomValues(array);
  return base64URLEncode(array);
}

// Usage: generate verifier up front and keep it until token exchange
const codeVerifier = generateCodeVerifier();
const codeChallenge = await generateCodeChallenge(codeVerifier);
console.log({ codeVerifier, codeChallenge });

import { Router, Request, Response } from 'express';
import axios from 'axios';

const router = Router();
const TOKEN_URL = process.env.TOKEN_URL;
const CLIENT_ID = process.env.CLIENT_ID;
const REDIRECT_URI = process.env.REDIRECT_URI;

router.get('/callback', async (req: Request, res: Response) => {
  const { code } = req.query;

  if (!code) {
    return res.status(400).send('Missing authorization code');
  }

  try {
    // Retrieve the code_verifier that was generated at the start
    // of this flow. It must be stored per-session or per-request.
    const codeVerifier = req.session.pkceCodeVerifier;

    if (!codeVerifier) {
      return res.status(400).send('PKCE code verifier not found');
    }

    // Build the token exchange request with PKCE
    const params = new URLSearchParams();
    params.append('grant_type', 'authorization_code');
    params.append('code', code as string);
    params.append('client_id', CLIENT_ID);
    params.append('redirect_uri', REDIRECT_URI);
    params.append('code_verifier', codeVerifier);

    const response = await axios.post(TOKEN_URL, params, {
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    });

    const { access_token, refresh_token, id_token } = response.data;

    // Tokens are now safely exchanged — the code could have been
    // intercepted, but without the verifier it is useless to an attacker
    req.session.accessToken = access_token;
    req.session.refreshToken = refresh_token;
    req.session.idToken = id_token;

    res.redirect('/dashboard');
  } catch (error: any) {
    console.error('PKCE token exchange failed:', error.response?.data);
    res.status(500).send('Authentication failed');
  }
});

// General Programming Example
class Example {
  constructor(config) {
    this.config = {
      enabled: true,
      debug: false,
      maxRetries: 3,
      timeout: 5000,
      ...config
    };
  }

  async process(input) {
    // Step 1: Validate input
    this.validate(input);

    // Step 2: Process with retry logic
    let attempts = 0;
    while (attempts < this.config.maxRetries) {
      try {
        const result = await this.execute(input);
        return { success: true, data: result };
      } catch (error) {
        attempts++;
        if (attempts >= this.config.maxRetries) {
          return { success: false, error: error.message };
        }
      }
    }
  }

  validate(input) {
    if (!input) {
      throw new Error('Input cannot be null or undefined');
    }
  }

  async execute(input) {
    // Implementation here
    return { processed: true, timestamp: Date.now() };
  }
}

// Usage
const example = new Example({ debug: true });
example.process({ id: 1 }).then(console.log);
